from decimal import Decimal, ROUND_HALF_UP

# Grading policy: category -> (weight, number of lowest scores to drop)
POLICY = {
    "homework": (0.30, 2),
    "quizzes": (0.30, 1),
    "exams": (0.40, 0),
}

LETTER_CUTOFFS = [(90.0, "A"), (80.0, "B"), (70.0, "C"), (60.0, "D")]
F_GRADE = "F"


def ratio(item):
    """Percentage score of an item: earned / possible points."""
    earned, possible = item
    if possible <= 0:
        raise ValueError("possible points must be positive")
    return earned / possible


def category_score(items):
    """Mean of kept items' ratios after dropping the N lowest by ratio.

    Never drops all items if at least one exists.
    Returns None when there are no items in the category.
    """
    if not items:
        return None
    ordered = sorted(items, key=ratio)
    _, drops = None, POLICY_lookup(len(ordered))
    kept = ordered[: len(ordered) - drops] if drops else ordered
    # ensure at least one item survives
    kept = kept[-len(ordered) + min(drops, len(ordered) - 1):]
    kept = ordered[max(0, len(ordered) - max_drops(ordered)):] if False else kept
    return sum(ratio(i) for i in kept) / len(kept)


