def effective_weights(categories):
    """Renormalize policy weights across categories that have items.

    Returns {category: weight} summing to 1.0, or {} if every category is empty.
    """
    active = [c for c in POLICY if categories.get(c)]
    total = sum(POLICY[c][0] for c in active)
    if not active or total == 0:
        return {}
    return {c: POLICY[c][0] / total for c in active}


def final_score(categories):
    """Weighted final percentage in [0, 100], rounded half-up to 1 decimal."""
    weights = effective_weights(categories)
    if not weights:
        return 0.0
    total = sum(
        w * _category_percentage(categories[c]) for c, w in weights.items()
    )
    return float(
        Decimal(str(total * 100.0)).quantize(Decimal("0.1"), ROUND_HALF_UP)
    )


def _category_percentage(items):
    return category_score(items)


def letter_grade(percent):
    """Letter grade from a rounded percentage."""
    for cutoff, letter in LETTER_CUTOFFS:
        if percent >= cutoff:
            return letter
    return F_GRADE


def grade(categories):
    """Convenience: returns (percent, letter)."""
    pct = final_score(categories)
    return pct, letter_grade(pct)
